{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "Ensure IAM policies are attached only to groups or roles",
      "resource": "aws_iam_user_policy_attachment.privesc3-passrole-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching IAM policies directly to users instead of groups or roles can lead to privilege escalation and is against best practices."
    },
    {
      "check_id": "UNKNOWN",
      "title": "IAM policy ARN is overly permissive",
      "resource": "aws_iam_policy_attachment.privesc3-passrole-user-attach-policy (implied)",
      "severity": "HIGH",
      "explanation": "The policy ARN 'aws_iam_policy.fn1-passrole-star.arn' suggests a policy named 'fn1-passrole-star', implying it might have overly broad permissions (e.g., 'iam:PassRole' with '*')."
    }
  ],
  "patched_code": "resource \"aws_iam_group\" \"privesc3_group\" {\n  name = \"privesc3_group\"\n}\n\nresource \"aws_iam_user_group_membership\" \"privesc3_user_group_membership\" {\n  user = aws_iam_user.fn1-privesc3-partial-user.name\n  groups = [aws_iam_group.privesc3_group.name]\n}\n\nresource \"aws_iam_group_policy_attachment\" \"privesc3-passrole-group-attach-policy\" {\n  group      = aws_iam_group.privesc3_group.name\n  policy_arn = aws_iam_policy.fn1-passrole-star.arn\n}",
  "fix_summary": "Created an IAM group, added the user to the group, and attached the policy to the group instead of the user to follow best practices."
}
